<?php use App\Core\Security;require BASE_PATH.'/app/Views/layout/header.php';?><div class="d-flex justify-content-between mb-3"><div><h2>Stock verification</h2><p class="text-muted">Compare system quantities with physical counts.</p></div><a class="btn btn-pink" href="<?= BASE_URL ?>/?page=stock&action=create">+ Verify stock</a></div><div class="card p-3"><table class="table"><thead><tr><th>Book</th><th>Expected</th><th>Counted</th><th>Difference</th><th>Checked by</th><th>Date</th><th>Action</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?= Security::e($r['title']) ?></td><td><?= $r['expected_quantity'] ?></td><td><?= $r['counted_quantity'] ?></td><td><?= $r['difference'] ?></td><td><?= Security::e($r['checked_by_name']) ?></td><td><?= Security::e($r['checked_at']) ?></td><td><form method="post" action="<?= BASE_URL ?>/?page=stock&action=delete" onsubmit="return confirm('Delete this stock verification record?');"><input type="hidden" name="_csrf" value="<?= Security::csrf() ?>"><input type="hidden" name="id" value="<?= $r['id'] ?>"><button class="btn btn-sm btn-outline-danger">Delete</button></form></td></tr><?php endforeach;?></tbody></table></div><?php require BASE_PATH.'/app/Views/layout/footer.php';?>
